namespace{EXCEPTION_INFO*P(PbExceptionInfoHandle h){return reinterpret_cast<EXCEPTION_INFO*>(h);}PbExceptionInfoHandle H(EXCEPTION_INFO*p){return reinterpret_cast<PbExceptionInfoHandle>(p);}PbStatus Copy(const std::string&s,char*b,uint64_t c,uint64_t*r){*r=s.size()+1;if(!b||c<*r)return PB_ERR_BUFFER_TOO_SMALL;std::memcpy(b,s.c_str(),static_cast<size_t>(*r));return PB_OK;}EXCEPTION_INFO*New(){return static_cast<EXCEPTION_INFO*>(std::malloc(sizeof(EXCEPTION_INFO)));}}
